import React from "react";
import { FEATURES } from "./Content";
import { Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck } from "lucide-react";

const icons = [Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck];

export default function WhyChooseUs() {
  return (
    <section id="why" className="relative px-6 md:px-12 lg:px-24 py-24 md:py-32" style={{ background: "linear-gradient(180deg, #faf8f5 0%, #fff9ed 100%)" }}>
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 mb-12">
        <div className="lg:col-span-5">
          <div className="overline mb-4">Why Choose Us</div>
          <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 400, color: "#1a080a" }}>
            Built for <span style={{ color: "#d4af37", fontStyle: "italic" }}>professionals</span> who care about finish.
          </h2>
        </div>
        <p className="lg:col-span-6 lg:col-start-7 max-w-xl" style={{ color: "rgba(26,8,10,0.65)", lineHeight: 1.7 }}>
          Six promises that have kept India's most demanding decorators coming back. From custom sizing to nationwide logistics - we keep your event on schedule and on style.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {FEATURES.map((f, i) => {
          const Icon = icons[i % icons.length];
          return (
            <div key={f.title} className="p-8 rounded-2xl transition-all duration-500 card-hover border-gradient cursor-pointer" style={{ background: "rgba(255,255,255,0.7)", backdropFilter: "blur(20px)", border: "1px solid rgba(255,255,255,0.8)", boxShadow: "0 8px 32px rgba(0,0,0,0.06)" }}>
              <div className="w-14 h-14 rounded-xl flex items-center justify-center mb-6 glass-card">
                <Icon size={26} strokeWidth={1.4} color="#d4af37" />
              </div>
              <h3 className="serif mb-3" style={{ fontSize: 24, color: "#1a080a", fontWeight: 400 }}>{f.title}</h3>
              <p style={{ color: "rgba(26,8,10,0.65)", fontSize: 14, lineHeight: 1.6 }}>{f.desc}</p>
            </div>
          );
        })}
      </div>
    </section>
  );
}
